async def have_conversation(self):
        history = []
        while True:
            query = input("Enter your math query (or 'exit' to quit): ")
            if query.lower() == 'exit':
                break
            else:
                history.append({"role": "user", "content": query})
                response = await self._process_query(history)
                print(f"AI: {response}")

def power(base: int, exponent: int) -> int:
    """Take a to the power of b"""
    print(f"System Message: Using power tool with base={base}, exponent={exponent}")
    return pow(base, exponent)

def find_last_agent_conversation(logs):
        for entry in reversed(logs):
            if entry.get("type") == "function_call_output":
                output_str = entry.get("output", "")
                try:
                    output_dict = ast.literal_eval(output_str)
                    if "assistant" in output_dict:
                        last_agent_name = output_dict["assistant"].lower().replace(" ", "_")
                        return last_agent_name
                except Exception:
                    continue
        return "unknown_agent"

def find_last_agent_from_transfers(logs, start_agent, agents):
        last_agent = start_agent
        for entry in logs:
            if entry.get("type") == "function_call":
                function_name = entry.get("name", "")
                if function_name.startswith("transfer_to_"):
                    agent_name = function_name.replace("transfer_to_", "")
                    agent = next((a for a in agents if a.name == agent_name), None)
                    if agent:
                        last_agent = agent
                    else:
                        continue
        return last_agent

def main(code_file: Path):
    code = code_file.read_text()

    query = f"""\
    Please write a markdown report that provides a complexity analysis of the following code. 
    State any assumptions you make. 

    Code:
    {code}
    """

    resp = client.chat.completions.create(
        model='o1-preview',
        messages=[
            {'role': 'user', 'content': query}
        ]
    )
    print(resp.choices[0].message.content)

def load_env():
    with open('secrets.env') as file:
        for line in file:
            line = line.strip()
            if not line or line.startswith('#'):
                continue

            key, value = line.split('=')
            os.environ[key] = value

def prompt_input():
    response = input('User: ')
    if not response:
        return None
    role = 'system' if response.startswith('!') else 'user'
    return dict(role=role, content=response.lstrip('!'))

def main(starter_history_file: str | None):

    if starter_history_file:
        with open(starter_history_file) as f:
            history = json.load(f)
    else:
        history = []

    for message in history:
        print(f'{message["role"]}: {message["content"]}')

    while (response := prompt_input()) is not None:
        history.append(response)
        if history[-1]['role'] == 'system':
            continue

        completion = client.chat.completions.create(
            model=ENGINE,
            messages=history
        )
        print('Assistant:', completion.choices[0].message.content)
        history.append({
            "role": completion.choices[0].message.role,
            "content": completion.choices[0].message.content
        })

