def _remove_private_keys_from_rubric(rubric):
    keys_to_remove = [key for key, val in rubric.items() if key[0] == '_']
    for key in keys_to_remove:
        rubric.pop(key)
    return rubric

def _flatten_report_and_rubric_items(report_contents, rubric):
    report = markdowndata.loads(report_contents)

    def helper_func(name, rubric_section, report_section):
        for section_name in rubric_section.keys():
            name.append(section_name)
            if isinstance(rubric_section[section_name], dict):
                yield from helper_func(name, rubric_section[section_name], report_section[section_name])
            elif isinstance(rubric_section[section_name], list):
                for section_item in rubric_section[section_name]:
                    yield name[::], section_item, report_section[section_name]
            name.pop(-1)

    flattened = list(helper_func([], rubric, report))
    return flattened

def helper_func(name, rubric_section, report_section):
        for section_name in rubric_section.keys():
            name.append(section_name)
            if isinstance(rubric_section[section_name], dict):
                yield from helper_func(name, rubric_section[section_name], report_section[section_name])
            elif isinstance(rubric_section[section_name], list):
                for section_item in rubric_section[section_name]:
                    yield name[::], section_item, report_section[section_name]
            name.pop(-1)

def _dict_to_md(d, level=1):
    """
    Convert a nested dict of the form
    {a: {b: {c: [1]}}}
    into markdown:

    # a
    ## b
    ### c
    - 1
    """
    lines = []

    for key, value in d.items():
        # Header line
        header_prefix = "#" * level
        lines.append(f"{header_prefix} {key}")

        # Nested dict → go one level deeper
        if isinstance(value, dict):
            lines.append(_dict_to_md(value, level + 1))

        # List → bullet items
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    lines.append(_dict_to_md(item, level + 1))
                else:
                    lines.append(f"- {item}")

        # Fallback: non-dict, non-list leaf
        else:
            lines.append(f"- {value}")

    return "\n".join(lines)

def _parse_s3_uri(s3_uri: str) -> tuple[str, str]:
    """Parse an s3:// URI into (bucket, key_or_prefix)."""
    if not s3_uri.startswith("s3://"):
        raise ValueError(f"Invalid S3 URI: {s3_uri}. Expected format: s3://bucket/key")

    body = s3_uri[len("s3://"):]
    if "/" not in body:
        raise ValueError(f"Invalid S3 URI: {s3_uri}. Missing key or prefix.")

    bucket, key_or_prefix = body.split("/", 1)
    if not bucket or not key_or_prefix:
        raise ValueError(f"Invalid S3 URI: {s3_uri}. Missing bucket or key/prefix.")

    return bucket, key_or_prefix

def _metadata_exists(s3, bucket: str, meta_key: str) -> bool:
    """Check if metadata JSON exists in S3."""
    try:
        s3.head_object(Bucket=bucket, Key=meta_key)
        return True
    except s3.exceptions.ClientError as e:
        if e.response["Error"]["Code"] == "404":
            return False
        raise

def _load_csv_from_s3(s3, bucket: str, key: str) -> pd.DataFrame:
    """Load a CSV from S3 with UTF-8 fallback encoding."""
    obj = s3.get_object(Bucket=bucket, Key=key)
    data_bytes = obj["Body"].read()
    try:
        df = pd.read_csv(BytesIO(data_bytes))
    except UnicodeDecodeError:
        duck_logger.warning(f"UTF-8 decoding failed for {key}, trying latin-1...")
        df = pd.read_csv(BytesIO(data_bytes), encoding="latin-1")
    return df

def _infer_dtype_dynamic(series: pd.Series, max_categories: int = MAX_CATEGORIES) -> str:
    """
    Dynamically infer dtype from the actual CSV column.
    - Numeric → int or float
    - String / object → string: val1, val2, etc.
    """
    s = series.dropna()
    if s.empty:
        return "string"

    if pd.api.types.is_integer_dtype(s):
        return "int"
    if pd.api.types.is_float_dtype(s):
        if (s % 1 == 0).all():
            return "int"
        return "float"

    try:
        s_numeric = pd.to_numeric(s, errors="coerce")
        if s_numeric.notna().all():
            return "int" if (s_numeric % 1 == 0).all() else "float"
    except Exception:
        pass

    unique_vals = pd.Series(s.astype(str).str.strip()).unique()
    if len(unique_vals) == 0:
        return "string"
    elif len(unique_vals) <= max_categories:
        return f"string: {', '.join(unique_vals)}"
    else:
        return f"string: {', '.join(unique_vals[:max_categories])}, etc."

def _draft_metadata(df: pd.DataFrame, dataset_name: str, bucket: str, key: str) -> dict:
    """Create draft metadata dict from a DataFrame."""
    duck_logger.info(f"Creating draft metadata for {dataset_name}")
    columns = []
    for col in df.columns:
        dtype = _infer_dtype_dynamic(df[col])
        columns.append({
            "col_name": col,
            "display_name": col.replace("_", " ").title(),
            "description": "",
            "dtype": dtype
        })
        duck_logger.debug(f"Column {col}: dtype={dtype}")
    draft_meta = {
        "dataset_name": dataset_name,
        "description": "",
        "columns": columns
    }
    return draft_meta

def generate_s3_metadata(s3_prefix: str, bucket: str, mode: str = "create", dry_run: bool = False) -> dict:
    """
    Reads all CSV datasets under the given S3 prefix and generates GPT-refined metadata.
    Returns: dict of {dataset_name: meta_json_dict}
    """
    duck_logger.info(f"Connecting to S3 bucket: {bucket}")
    s3 = boto3.client("s3")
    paginator = s3.get_paginator("list_objects_v2")

    data_keys = []

    for page in paginator.paginate(Bucket=bucket, Prefix=s3_prefix):
        for obj in page.get("Contents", []):
            key = obj["Key"]
            if _is_txt(key):
                key = _convert_txt_to_csv_in_s3(s3, bucket, key)
            if _is_csv(key):
                data_keys.append(key)

    metadata_dict = {}
    for key in data_keys:
        refined_meta = _process_dataset(s3, bucket, key, mode, dry_run=dry_run)
        if refined_meta:
            metadata_dict[Path(key).stem] = refined_meta

    duck_logger.info(f"Metadata generation complete. Total metadata files created: {len(metadata_dict)}")
    return metadata_dict

def generate_metadata_for_s3_uri(s3_uri: str, mode: str = "create", dry_run: bool = False) -> dict:
    """
    Generate metadata for datasets selected by a single S3 URI.
    The URI may point to one file or a prefix.
    """
    bucket, key_or_prefix = _parse_s3_uri(s3_uri)
    s3 = boto3.client("s3")
    data_keys = _collect_keys_from_uri(s3, bucket, key_or_prefix)

    if not data_keys:
        duck_logger.warning(f"No CSV/TXT datasets found for {s3_uri}")
        return {}

    metadata_dict = {}
    for key in sorted(data_keys):
        resolved_key = _convert_txt_to_csv_in_s3(s3, bucket, key) if _is_txt(key) else key
        refined_meta = _process_dataset(s3, bucket, resolved_key, mode, dry_run=dry_run)
        if refined_meta:
            metadata_dict[Path(resolved_key).stem] = refined_meta

    duck_logger.info(f"Processed {len(metadata_dict)} dataset(s) from {s3_uri}")
    return metadata_dict

def main(s3_uri: str | None, mode: str, dry_run: bool, model: str):
    global MODEL
    MODEL = model

    duck_logger.info(
        f"Starting metadata generation (mode={mode}, dry_run={dry_run}, model={model})"
    )
    if s3_uri:
        all_meta = generate_metadata_for_s3_uri(s3_uri, mode=mode, dry_run=dry_run)
    else:
        # backward-compatible default behavior
        bucket = "stats121-datasets"
        prefix = "datasets/"
        all_meta = generate_s3_metadata(prefix, bucket, mode=mode, dry_run=dry_run)

    for dataset_name, meta in all_meta.items():
        if dry_run:
            duck_logger.info(f"\n--- Metadata for {dataset_name} ---\n")
            duck_logger.info(json.dumps(meta, indent=2))
        else:
            duck_logger.debug(f"\n--- Metadata for {dataset_name} ---\n")
            duck_logger.debug(json.dumps(meta, indent=2))

def fetch_content(infile: str) -> str:
    with open(infile) as file:
        return file.read()

def id_issues(md_prompt: str, code: str, yaml_filename: str):
    curr_step = run_agent(
        agent='codex',
        input={
            "code": code,
            "filename": yaml_filename
        },
        output={
            "error": "true if running the code threw a traceback error, else false",
            "next_code": "The code after a single fix is implemented"
        },
        prompt=md_prompt
    )

    if curr_step.status != "completed":
        raise RuntimeError(
            f"Agent failed: {curr_step.error_type}: {curr_step.error_message}"
        )

    next_code = str(curr_step.output.get("next_code", ""))

    if str(curr_step.output["error"]).lower() == "true":
        populate_error_code_fields(Path(yaml_filename), code)
        return id_issues(md_prompt, next_code, yaml_filename)

    populate_correct_code_field(Path(yaml_filename), next_code)
    return

def populate_correct_code_field(rubric_path: Path, source_code: str | None = None) -> None:
    if not source_code:
        return

    rubric = _load_rubric(rubric_path)
    if "correct code" not in rubric:
        rubric["correct code"] = _number_code_lines(source_code)
    rubric_path.write_text(safe_dump(rubric, sort_keys=False))

def _load_rubric(rubric_path: Path) -> dict:
    if not rubric_path.exists():
        return {}
    return safe_load(rubric_path.read_text()) or {}

def _populate_error_code_fields(value, source_code: str | None = None):
    if isinstance(value, dict):
        populated = {
            key: _populate_error_code_fields(nested_value, source_code)
            for key, nested_value in value.items()
        }
        if "traceback" in populated:
            line_number, code_line = _traceback_error_location(populated["traceback"])
            if not populated.get("code"):
                populated["code"] = _code_field(source_code, line_number, code_line)
            if line_number and code_line and not populated.get("error line"):
                populated["error line"] = [f"line {line_number}: {code_line}"]
        return populated

    if isinstance(value, list):
        return [
            _populate_error_code_fields(item, source_code)
            for item in value
        ]

    return value

def _code_field(source_code: str | None, line_number: str, code_line: str) -> str:
    if source_code:
        return _number_code_lines(source_code)

    if line_number and code_line:
        return f"{int(line_number):02}| {code_line}"

    return ""

def _number_code_lines(source_code: str) -> str:
    return "\n".join(
        f"{line_number:02}| {line}"
        for line_number, line in enumerate(source_code.splitlines(), start=1)
    )

def _traceback_error_location(value) -> tuple[str, str]:
    lines = _rubric_text(value).splitlines()
    for index, line in enumerate(lines):
        location_match = TRACEBACK_LOCATION_PATTERN.search(line)
        if not location_match:
            continue

        code_line = _next_traceback_code_line(lines[index + 1:])
        return location_match.group("line"), code_line

    return "", ""

def _rubric_text(value) -> str:
    if isinstance(value, str):
        return value

    if isinstance(value, list):
        return "\n".join(_rubric_text(item) for item in value)

    if isinstance(value, dict):
        return "\n".join(_rubric_text(item) for item in value.values())

    if value is None:
        return ""

    return str(value)

def _next_traceback_code_line(lines: list[str]) -> str:
    for line in lines:
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith("^"):
            continue
        return stripped_line
    return ""

def conceal_traceback_paths(rubric_path: Path, source_path: Path) -> None:
    rubric = safe_load(rubric_path.read_text()) or {}
    concealed_root = _concealed_root(rubric_path)
    concealed_rubric = _conceal_traceback_values(rubric, concealed_root, source_path.name)
    rubric_path.write_text(safe_dump(concealed_rubric, sort_keys=False))

def _conceal_traceback_values(value, concealed_root: str, fallback_filename: str):
    if isinstance(value, dict):
        return {
            key: _conceal_traceback_field(nested_value, concealed_root, fallback_filename)
            if key == "traceback"
            else _conceal_traceback_values(nested_value, concealed_root, fallback_filename)
            for key, nested_value in value.items()
        }

    if isinstance(value, list):
        return [
            _conceal_traceback_values(item, concealed_root, fallback_filename)
            for item in value
        ]

    return value

def _conceal_traceback_field(value, concealed_root: str, fallback_filename: str):
    if isinstance(value, str):
        return _conceal_paths(value, concealed_root, fallback_filename)

    if isinstance(value, list):
        return [
            _conceal_traceback_field(item, concealed_root, fallback_filename)
            for item in value
        ]

    if isinstance(value, dict):
        return {
            key: _conceal_traceback_field(nested_value, concealed_root, fallback_filename)
            for key, nested_value in value.items()
        }

    return value

def _conceal_paths(text: str, concealed_root: str, fallback_filename: str) -> str:
    def replace(match: re.Match) -> str:
        filename = match.group("filename") or fallback_filename
        return f'{match.group("quote")}{concealed_root}/{filename}{match.group("quote")}'

    return TRACEBACK_PATH_PATTERN.sub(replace, text)

def replace(match: re.Match) -> str:
        filename = match.group("filename") or fallback_filename
        return f'{match.group("quote")}{concealed_root}/{filename}{match.group("quote")}'

def __init__(self, send_message: Callable):
        self._tools: dict[str, Callable] = {}
        self._schemas: dict[str, FunctionToolParam] = {}
        self._send_message = send_message

def scrub_tools(self, tool_instance: object):
        for attr_name in dir(tool_instance):
            if attr_name.startswith("_"):
                continue

            method = getattr(tool_instance, attr_name)
            if not callable(method):
                continue

            if not hasattr(method, "is_tool"):
                continue

            self.add_tool(method)

def _wrap_tool_with_context(self, func: Callable) -> Callable:
        sig = inspect.signature(func)
        params = list(sig.parameters.values())

        if params and params[0].name == "ctx":
            return func

        if inspect.iscoroutinefunction(func):
            @wraps(func)
            async def wrapper(ctx: DuckContext, *args, **kwargs):
                return await func(*args, **kwargs)
        else:
            @wraps(func)
            def wrapper(ctx: DuckContext, *args, **kwargs):
                return func(*args, **kwargs)

        return wrapper

def add_tool(self, tool_function: Callable, name=None, description=None):
        if name is None:
            name = tool_function.__name__
        if description is None:
            description = tool_function.__doc__

        @functools.wraps(tool_function)
        async def _tool(*args, **kwargs):
            return await tool_function(*args, **kwargs)

        _tool.__name__ = name
        _tool.__doc__ = description

        wrapped = self._wrap_tool_with_context(_tool)

        if hasattr(_tool, "sends_image"):
            wrapped = self.send_image_directly(wrapped)

        self._schemas[_tool.__name__] = generate_function_schema(_tool)

        completes_response = hasattr(_tool, 'complete_response')

        if inspect.iscoroutinefunction(wrapped):
            async def wrapper(ctx: DuckContext, *args, **kwargs):
                result = await wrapped(ctx, *args, **kwargs)
                if isinstance(result, ConcludesResponse):
                    return result.result, True
                return result, completes_response
        else:
            def wrapper(ctx: DuckContext, *args, **kwargs):
                result = wrapped(ctx, *args, **kwargs)
                if isinstance(result, ConcludesResponse):
                    return result.result, True
                return result, completes_response

        self._tools[_tool.__name__] = wrapper

def wrapper(ctx: DuckContext, *args, **kwargs):
                result = wrapped(ctx, *args, **kwargs)
                if isinstance(result, ConcludesResponse):
                    return result.result, True
                return result, completes_response

def get_specific_tool(self, tool_name: str):
        if tool_name in self._tools:
            return self._tools[tool_name]
        raise KeyError(f"Tool '{tool_name}' not found in any armory module.")

def get_tool_schema(self, tool_name: str) -> FunctionToolParam:
        if tool_name in self._schemas:
            return self._schemas[tool_name]
        raise KeyError(f"Tool '{tool_name}' not found in any armory module.")

def send_image_directly(self, func):
        @wraps(func)
        async def wrapper(ctx, *args, **kwargs) -> tuple[None, bool]:
            if inspect.iscoroutinefunction(func):
                result = await func(ctx, *args, **kwargs)
            else:
                result = func(ctx, *args, **kwargs)

            name, _ = result
            await self._send_message(ctx.thread_id, file=result)
            return None

        return wrapper

def _to_plain_decimal(token: str) -> str:
    try:
        value = Decimal(token)
    except InvalidOperation:
        return token

    if not value.is_finite():
        return token

    formatted = format(value, "f")
    if "." in formatted:
        formatted = formatted.rstrip("0").rstrip(".")
    if formatted in {"", "-0", "+0"}:
        return "0"
    return formatted

def _format_table_values(table: pd.DataFrame) -> pd.DataFrame:
    formatted_table = table.copy()
    for col in formatted_table.columns:
        if not is_numeric_dtype(formatted_table[col]):
            continue
        formatted_table[col] = formatted_table[col].map(
            lambda value: _format_rounded_decimal(value, 4) if pd.notna(value) else ""
        )
    return formatted_table

def _estimate_column_widths(df, sample_rows=20):
    widths = {}
    for col in df.columns:
        header_width = len(str(col))
        sample_width = (
            df[col]
            .astype(str)
            .head(sample_rows)
            .map(len)
            .max()
        )
        widths[col] = max(header_width, sample_width)
    return widths

def _determine_col_chunk(df, max_table_width=90):
    col_widths = _estimate_column_widths(df)

    current_width = 0
    current_chunk = 0

    for width in col_widths.values():
        # +3 accounts for markdown separators and padding
        projected = current_width + width + 4

        if projected > max_table_width and current_chunk > 0:
            break

        current_width = projected
        current_chunk += 1

    # ensure it's between 2 and 6
    return max(2, min(current_chunk, 6))

def _clean_stdout(stdout: str, files: dict[str, FileResult]) -> str:
    file_names = set(files.keys())

    filtered_lines = []
    for line in stdout.splitlines():
        stripped = line.strip()

        # drop filename echoes
        if stripped in file_names:
            continue

        # drop lines mentioning filenames
        if any(name in stripped for name in file_names):
            continue

        filtered_lines.append(line)

    stdout = "\n".join(filtered_lines).strip()
    return _remove_scientific_notation(stdout)

async def run_code(self, ctx: DuckContext, code: str, user_intent: str) -> dict[str, str | dict[str, str]]:
        """
        Takes python code and the user's intent, executes it, and returns stdout/stderr/files.

        :param ctx: DuckContext
        :param code: Python code to execute
        :param user_intent: Short description of what the user is trying to do.
        :return:
            'code': str,
            'stdout': str,
            'stderr': str,
            'files': {
                filename: description
            }
        """
        key = None
        if self._tool_cache and self._cache_key_builder:
            cache_key = self._cache_key_builder.build_cache_key(user_intent, code)
            key = self._tool_cache.get_key(cache_key)
            duck_logger.debug(f"Cache key: {key}")

            if self._tool_cache.check_if_cached(key):
                duck_logger.debug(f" Cache HIT ".center(20, '-'))
                output = await self._tool_cache.send_from_cache(
                    key,
                    self._send_message,
                    ctx.thread_id
                )
                return ConcludesResponse(output)

            duck_logger.debug(f" Cache MISS ".center(19, '-'))
        else:
            duck_logger.debug(f" Cache DISABLED ".center(21, '-'))
        results = await self._container.run_code(code)

        stdout = results.get('stdout').strip()
        stderr = _remove_scientific_notation(results.get('stderr').strip())
        files = results.get('files', {})

        # log created files
        if files:
            duck_logger.debug(" files ".center(20, '-'))
            for filename, file in files.items():
                duck_logger.debug(f" {filename}: {file['description']}")

        # send files directly
        for filename, file in files.items():
            if is_image(filename):
                if self._tool_cache and key is not None:
                    self._tool_cache.cache_file(key, filename, file)
                await self._send_message(
                    ctx.thread_id,
                    file={
                        "filename": filename,
                        "bytes": file["bytes"],
                    }
                )
            elif is_table(filename):
                table = pd.read_csv(io.StringIO(file['bytes'].decode()))
                table_chunks = await send_table(
                    self._send_message,
                    ctx.thread_id,
                    table,
                )
                if self._tool_cache and key is not None:
                    self._tool_cache.cache_table(key, filename, table_chunks, file.get("description", ""))

        # send cleaned stdout directly
        stdout = _clean_stdout(stdout, files)
        if stdout:
            if self._tool_cache and key is not None:
                self._tool_cache.cache_msg(key, stdout)
            await self._send_message(ctx.thread_id, stdout)

        output = {
            'stdout': stdout,
            'stderr': stderr,
            'files': {filename: file['description'] for filename, file in files.items()},
        }

        if results['exit_code'] == 0:
            output = ConcludesResponse(output)

        return output

