        duck_logger.info(f"Initialized FeedbackManager with queues for channels: {list(queues.keys())}")

def remember_conversation(self, feedback_data: FeedbackData):
        queue = self._queues.get(feedback_data['parent_channel_id'])
        if queue is not None:
            duck_logger.info(
                f"Remembering conversation for channel {feedback_data['parent_channel_id']}: {feedback_data}")
            queue.put(feedback_data)
        else:
            duck_logger.debug(f"No queue found for channel {feedback_data['parent_channel_id']} when remembering")

def __init__(self, SQLMetricsHandler, server_configs: dict[str, ServerConfig], reporting_config: ReporterConfig, show_fig=False):
        self.SQLMetricsHandler = SQLMetricsHandler
        wrap_steps(self.SQLMetricsHandler, ["record_message", "record_usage", "record_feedback"])
        self._pricing = reporting_config['gpt_pricing']
        self.show_fig = show_fig
        self._reporting_config = self._make_reporting_config(server_configs)
        # Create a flat mapping of channel IDs to channel names
        self._channels = {}
        for server_channels in self._reporting_config.values():
            self._channels.update({int(channel_id): channel_name for channel_id, channel_name in server_channels.items()})

def _make_reporting_config(self, server_configs: dict[str, ServerConfig]) -> dict:
        """This function converts the server_config into a dictionary that maps server names to their channels."""
        reporting_config = {}
        for server_name, server in server_configs.items():
            channel_dict = {}
            for channel_name, channel in server['channels'].items():
                channel_id = channel['channel_id']
                channel_dict[channel_id] = channel_name
            reporting_config[server_name] = channel_dict
        return reporting_config

def select_dataframe(self, desired_df):
        if desired_df == 'feedback':
            data = self.SQLMetricsHandler.get_feedback()
        elif desired_df == 'usage':
            data = self.SQLMetricsHandler.get_usage()
        elif desired_df == 'messages':
            data = self.SQLMetricsHandler.get_message()
        else:
            raise ArgumentError(None, f"Invalid dataframe: {desired_df}")

        duck_logger.debug(f"Raw data from SQLMetricsHandler: {data}")

        # Convert list to DataFrame if necessary
        if isinstance(data, list):
            # Use first row as column names
            columns = data[0]
            df = pd.DataFrame(data[1:], columns=columns)
            duck_logger.debug(f"Converted to DataFrame - Shape: {df.shape}")
            duck_logger.debug(f"DataFrame columns: {df.columns.tolist()}")
            duck_logger.debug(f"Sample data:\n{df.head()}")
            return df
        return data

def catch_known_issues(self, df, args):
        if args.ind_var not in df.columns:
            raise ArgumentError(None, f"Invalid independent variable: {args.ind_var}")

        if args.exp_var and args.exp_var not in df.columns:
            raise ArgumentError(None, f"Invalid explanatory variable: {args.exp_var}")

        if args.period and args.period not in self.time_periods:
            raise ArgumentError(None, f"Invalid time period: {args.period}")

def prepare_df(self, df, args):
        if isinstance(df, list):
            columns = df[0]
            df = pd.DataFrame(df[1:], columns=columns)

        df = self.preprocessing(df, args)

        # Check if DataFrame is empty or has no data
        if df.empty or (len(df.columns) == 1 and df.columns[0] == 'No data available'):
            return pd.DataFrame()  # Return empty DataFrame

        self.catch_known_issues(df, args)

        duck_logger.debug(f"Data before grouping - Shape: {df.shape}")
        duck_logger.debug(f"Columns: {df.columns.tolist()}")
        duck_logger.debug(f"Sample data:\n{df.head()}")
        duck_logger.debug(f"Unique values in hour_of_day: {df['hour_of_day'].unique() if 'hour_of_day' in df.columns else 'No hour_of_day column'}")
        duck_logger.debug(f"Unique values in cost: {df['cost'].unique() if 'cost' in df.columns else 'No cost column'}")

        if args.exp_var_2:
            if not pd.api.types.is_numeric_dtype(df[args.ind_var]):
                df_grouped = df.groupby([args.exp_var, args.exp_var_2])[args.ind_var].count().reset_index()
            elif args.average:
                df_grouped = df.groupby([args.exp_var, args.exp_var_2])[args.ind_var].mean().reset_index()
            elif args.count:
                df_grouped = df.groupby([args.exp_var, args.exp_var_2])[args.ind_var].nunique().reset_index()
            elif args.percent:
                df_grouped = df.groupby([args.exp_var, args.exp_var_2])[args.ind_var].apply(
                    lambda x: x.notna().mean() * 100).reset_index()
            else:
                df_grouped = df.groupby([args.exp_var, args.exp_var_2])[args.ind_var].sum().reset_index()

        elif args.exp_var:
            try:
                df[args.ind_var] = pd.to_numeric(df[args.ind_var], errors='coerce')
                if args.average:
                    df_grouped = df.groupby(args.exp_var)[args.ind_var].mean().reset_index()
                elif args.count:
                    df_grouped = df.groupby(args.exp_var)[args.ind_var].nunique().reset_index()
                elif args.percent:
                    df_grouped = df.groupby(args.exp_var)[args.ind_var].apply(
                        lambda x: x.notna().mean() * 100).reset_index()
                else:
                    df_grouped = df.groupby(args.exp_var)[args.ind_var].sum().reset_index()
            except ValueError:
                duck_logger.exception(f"Error converting {args.ind_var} to numeric")
                df_grouped = df.groupby(args.exp_var)[args.ind_var].count().reset_index()

        else:
            df_grouped = df[args.ind_var].reset_index()

        return df_grouped

def arg_to_string(self, args):
        components = [args.dataframe, args.ind_var]
        if args.percent:
            components.append("percent")
        if args.count:
            components.append("count")
        components += [attr for attr in [args.exp_var, args.exp_var_2, args.period] if attr]
        if args.log:
            components.append("log_scale")
        return "-".join(components)

def help_menu(self):
        lines = ["### Type `'!report'`, followed by any of the following commands to see the metrics for it:"]
        lines.extend(f" - `'{key}'`: {item[1]}" for key, item in self.pre_baked.items())
        return "\n".join(lines)

def get_all_prebaked(self):
        results = []
        for key, (command, description) in self.pre_baked.items():
            if key != 'all':  # Skip the 'all' command itself
                try:
                    result = self.get_report(f"!report {key}")
                    if isinstance(result, list):  # Only add if we got a valid image result
                        results.extend(result)
                    else:
                        duck_logger.warning(f"Skipping {key} - {result}")
                except Exception:
                    duck_logger.exception(f"Error generating report for {key}")
                    continue
        return results

def get_report(self, arg_string) -> list[tuple[str, io.BytesIO]] | str:
        try:
            if arg_string == '!report all':
                return self.get_all_prebaked()
            if arg_string in ['!report', '!report help', '!report h']:
                return self.help_menu()

            if arg_string == '!report ftrend percent' or arg_string == '!report ftrend average':
                title, image = feed_fancy_graph(self._channels, self.SQLMetricsHandler.get_feedback(), arg_string, self.show_fig)
                return [(title, image)]

            args = self.parse_args(arg_string)

            df = self.select_dataframe(args.dataframe)
            df_limited = self.prepare_df(df, args)

            if len(df_limited) == 0:
                return "No data available for this plot."

            title, image = self.make_graph(df_limited, args)
            return [(title, image)]

        except ArgumentError as e:
            return (
                "Invalid report command.\n"
                f"{e}\n\n"
                f"{self.help_menu()}\n\n"
                "Custom report format example:\n"
                "`!report -df usage -iv thread_id -c -ev hour_of_day -ev2 guild_id -p year`"
            )
        except Exception as e:
            # Ensure any matplotlib figures are closed
            plt.close('all')
            raise

def interactive_report(self):
        # Interactive report selection loop
        print("\nAvailable reports:")
        for key, (_, description) in self.pre_baked.items():
            print(f"  {key}: {description}")
        print("\nType 'help' to see this menu again")
        print("Type 'exit' to quit")
        while True:
            command = input("\nEnter report command (or 'help'/'exit'): ").strip()

            if command.lower() == 'exit':
                break
            elif command.lower() == 'help':
                print("\nAvailable reports:")
                for key, (_, description) in self.pre_baked.items():
                    print(f"  {key}: {description}")
                continue

            # Check if it's a pre-baked command
            if command in self.pre_baked:
                command = self.pre_baked[command][0]  # Get the actual command string
                if command is None:  # Handle special cases like ftrend
                    command = f"!report {command}"
            else:
                print(f"Unknown command: {command}")
                print("Type 'help' to see available commands")
                continue

            # Add !report prefix if not present
            if not command.startswith('!report'):
                command = f"!report {command}"

            print(f"Running command: {command}")  # Debug print
            self.get_report(command)

def _create_sqlite_session(db_name: str) -> Session:
    duck_logger.info(f'Creating SQLite session with name: {db_name}')
    db_url = f"sqlite:///{db_name}"
    engine = create_engine(db_url)
    return sessionmaker(bind=engine)()

def resolve_env_vars(config):
    return {
        key: os.getenv(value[len('env:'):]) if value.startswith('env:') else value
        for key, value in config.items()
    }

def create_sql_session(config: SqlConfig) -> Session:
    config = resolve_env_vars(config)
    if config['db_type'] == 'sqlite':
        return _create_sqlite_session(config['database'])
    else:
        return _create_sql_session(**config)

def add_iter(cls):
    def __iter__(self):
        for key in self.__table__.columns.keys():
            yield key, getattr(self, key)

    cls.__iter__ = __iter__
    return cls

def __iter__(self):
        for key in self.__table__.columns.keys():
            yield key, getattr(self, key)

def __init__(self, session: Session):
        MetricsBase.metadata.create_all(session.connection())
        self.session = session

def sql_model_to_data_list(self, table_model):
        try:
            data = []
            records = iter(self.session.query(table_model).all())
            header = next(records)
            data.append([key for key, _ in header])
            data.append([value for _, value in header])

            for record in records:
                data.append([value for _, value in record])

            return data
        except Exception:
            duck_logger.exception("Failed to query metrics table")
            raise

def __init__(self, name, session):
        self._name = name
        self._session = session

def write_blob(self, key: str, blob: Blob):
        session = self._get_session()
        record_to_update = session.query(RecordModel).filter(RecordModel.name == self._name,
                                                             RecordModel.key == key).one_or_none()
        if record_to_update:
            record_to_update.blob = blob
        else:
            new_record = RecordModel(name=self._name, key=key, blob=blob)
            session.add(new_record)
        session.commit()

def read_blob(self, key: str) -> Blob | None:
        records = self._get_session().query(RecordModel).filter(RecordModel.name == self._name).all()
        for record in records:
            if record.key == key:
                return record.blob

def has_blob(self, key: str) -> bool:
        records = self._get_session().query(RecordModel).filter(RecordModel.name == self._name).all()
        for record in records:
            if record.key == key:
                return True
        return False

def delete_blob(self, key: str):
        records = self._get_session().query(RecordModel).filter(RecordModel.name == self._name).all()
        for record in records:
            if record.key == key:
                self._get_session().delete(record)
                self._get_session().commit()

