        return await assess_conversations(
            ai_client=testerbot.ai_client,
            ctx=testerbot.last_context,
            history=history,
            assessors=assessor,
        )
    return await assess_conversation(
        ai_client=testerbot.ai_client,
        ctx=testerbot.last_context,
        history=history,
        assessor=assessor,
